function Button({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'quiet' | 'outline' | 'danger' }) {
  const styles = { primary: 'bg-primary text-primary-foreground hover:brightness-105', quiet: 'bg-muted text-foreground hover:bg-muted/70', outline: 'border border-border bg-card text-foreground hover:border-primary hover:text-primary', danger: 'bg-destructive text-destructive-foreground hover:brightness-105' };
  return <button className={`focus-ring inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold transition-all active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} {...props}>{children}</button>;
}

