function SearchBar({ compact = false, initial = '' }: { compact?: boolean; initial?: string }) {
  const [, navigate] = useLocation();
  const [value, setValue] = useState(initial);
  return <form onSubmit={(event) => { event.preventDefault(); navigate(`/properties?location=${encodeURIComponent(value)}`); }} className={`flex ${compact ? 'flex-col gap-2 sm:flex-row' : 'flex-col gap-3 md:flex-row'} rounded-2xl border border-border bg-card p-2 shadow-[0_16px_45px_-28px_hsl(195_31%_17%/.5)]`}>
    <div className="flex min-w-0 flex-1 items-center gap-3 rounded-xl px-3 py-2"><Search className="shrink-0 text-primary" size={19} /><input value={value} onChange={(event) => setValue(event.target.value)} data-testid="input-property-search" className="w-full bg-transparent text-sm font-semibold outline-none placeholder:text-muted-foreground" placeholder="Neighbourhood, district or landmark" /></div>
    <div className="hidden w-px bg-border md:block" /><select data-testid="select-property-type" className="rounded-xl bg-muted px-3 py-2 text-sm font-semibold outline-none"><option>Any home type</option><option>Apartment</option><option>House</option><option>Studio</option></select>
    <Button type="submit" className="shrink-0"><Search size={16} /> Search homes</Button>
  </form>;
}

function StatusPill({ status, verified }: { status?: string; verified?: boolean }) {
  if (verified) return <span className="inline-flex items-center gap-1 rounded-full bg-primary/10 px-2.5 py-1 text-[11px] font-bold text-primary"><BadgeCheck size={13} /> Verified</span>;
  return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-bold ${status === 'pending' ? 'bg-secondary/25 text-foreground' : status === 'paused' ? 'bg-accent/15 text-accent' : 'bg-muted text-muted-foreground'}`}>{status === 'pending' ? 'In review' : status === 'paused' ? 'Paused' : 'New listing'}</span>;
}

function PropertyCard({ property, saved = false, onSaved }: { property: Property; saved?: boolean; onSaved?: () => void }) {
  const add = useAddFavorite();
  const remove = useRemoveFavorite();
  const saving = add.isPending || remove.isPending;
  const toggle = () => { (saved ? remove : add).mutate({ propertyId: property.id }, { onSuccess: onSaved }); };
  return <article data-testid={`card-property-${property.id}`} className="lift overflow-hidden rounded-2xl border border-border bg-card">
    <div className="relative aspect-[1.22] overflow-hidden bg-muted">
      <img src={property.image || photos[0]} alt={property.title} loading="lazy" decoding="async" className="h-full w-full object-cover transition-transform duration-500 hover:scale-105" />
      <div className="absolute left-3 top-3"><StatusPill verified={property.verified} status={property.status} /></div>
      <button onClick={toggle} disabled={saving} aria-label={saved ? 'Remove saved home' : 'Save home'} data-testid={`button-save-property-${property.id}`} className={`focus-ring absolute right-3 top-3 grid h-9 w-9 place-items-center rounded-full backdrop-blur transition ${saved ? 'bg-secondary text-foreground' : 'bg-card/90 text-foreground hover:bg-secondary'}`}>{saving ? <LoaderCircle className="animate-spin" size={16} /> : <Heart size={17} fill={saved ? 'currentColor' : 'none'} />}</button>
    </div>
    <div className="p-4">
      <div className="flex items-start justify-between gap-2"><div><p className="mb-1 flex items-center gap-1 text-xs font-semibold text-muted-foreground"><MapPin size={12} className="text-accent" /> {property.location}</p><h3 className="font-display text-[17px] font-bold leading-tight">{property.title}</h3></div><ArrowUpRight size={17} className="mt-1 shrink-0 text-muted-foreground" /></div>
      <div className="mt-4 flex items-center gap-3 text-xs font-semibold text-muted-foreground"><span className="flex items-center gap-1"><BedDouble size={14} /> {property.bedrooms} bed</span><span>{property.bathrooms} bath</span>{property.size && <span>{property.size} m²</span>}</div>
      <div className="mt-4 flex items-end justify-between border-t border-border pt-3"><p><span className="font-display text-lg font-bold text-primary">{money(property.rent)}</span><span className="text-xs text-muted-foreground"> / month</span></p><Link href={`/properties/${property.id}`} data-testid={`link-property-${property.id}`} className="text-xs font-bold text-primary underline-link">View home</Link></div>
    </div>
  </article>;
}

function PropertyGrid({ properties, empty = 'No homes match those filters yet.', savedIds, onFavoriteChanged }: { properties: Property[]; empty?: string; savedIds?: Set<string>; onFavoriteChanged?: () => void }) {
  if (!properties.length) return <div className="col-span-full rounded-2xl border border-dashed border-border bg-card py-16 text-center"><Compass className="mx-auto text-primary" size={28} /><h3 className="mt-4 font-display text-xl font-bold">A quiet patch of map</h3><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">{empty}</p><Link href="/search" data-testid="link-empty-adjust-search" className="mt-5 inline-flex font-bold text-primary underline-link">Adjust your search <ArrowRight size={15} className="ml-1" /></Link></div>;
  return <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{properties.map((property) => <PropertyCard key={property.id} property={property} saved={savedIds?.has(property.id)} onSaved={onFavoriteChanged} />)}</div>;
}

function QueryState({ loading, error, retry, children }: { loading: boolean; error: boolean; retry: () => void; children: React.ReactNode }) {
  if (loading) return <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{[1, 2, 3].map((item) => <div key={item} className="overflow-hidden rounded-2xl border border-border bg-card"><div className="skeleton aspect-[1.22]" /><div className="space-y-3 p-4"><div className="skeleton h-3 w-24 rounded" /><div className="skeleton h-5 w-4/5 rounded" /><div className="skeleton h-4 w-3/5 rounded" /></div></div>)}</div>;
  if (error) return <div className="rounded-2xl border border-destructive/30 bg-destructive/5 py-14 text-center"><CircleAlert className="mx-auto text-destructive" /><p className="mt-3 font-bold">We could not load that just now.</p><p className="mt-1 text-sm text-muted-foreground">Try again, or explore our handpicked homes.</p><Button onClick={retry} variant="outline" className="mt-5">Try again</Button></div>;
  return <>{children}</>;
}

