     <section className="mx-auto max-w-7xl px-5 py-16 lg:px-8"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="font-mono-custom text-xs uppercase tracking-[.18em] text-accent">A good place to start</p><h2 className="mt-2 font-display text-3xl font-bold tracking-tight md:text-4xl">Homes worth a closer look.</h2></div><Link href="/properties" data-testid="link-home-all-properties" className="flex items-center gap-2 text-sm font-bold text-primary underline-link">See all homes <ArrowRight size={16} /></Link></div><div className="mt-8"><QueryState loading={isLoading} error={isError && !data?.length} retry={() => refetch()}><PropertyGrid properties={properties.slice(0, 3)} savedIds={savedIds} onFavoriteChanged={() => queryClient.invalidateQueries({ queryKey: getListFavoritesQueryKey() })} /></QueryState></div></section>
