function PropertiesPage() {
  const params = new URLSearchParams(window.location.search);
  const [location, setLocation] = useState(params.get('location') || '');
  const [type, setType] = useState('');
  const [minRent, setMinRent] = useState('');
  const [maxRent, setMaxRent] = useState('');
  const [bedrooms, setBedrooms] = useState('');
  const [advanceMonths, setAdvanceMonths] = useState('');
  const [amenity, setAmenity] = useState('');
  const [sort, setSort] = useState<'recommended' | 'lowest' | 'highest' | 'newest' | 'viewed'>('recommended');
  const filters = useMemo(() => ({
    location: location || undefined,
    type: type || undefined,
    minRent: minRent ? Number(minRent) : undefined,
    maxRent: maxRent ? Number(maxRent) : undefined,
    bedrooms: bedrooms ? Number(bedrooms) : undefined,
    advanceMonths: advanceMonths ? Number(advanceMonths) : undefined,
    amenity: amenity || undefined,
    sort,
  }), [location, type, minRent, maxRent, bedrooms, advanceMonths, amenity, sort]);
  const { data, isLoading, isError, refetch } = useListProperties(filters, { query: { queryKey: getListPropertiesQueryKey(filters) } });
  const properties = data ?? [];
  const savedQuery = useListFavorites({ query: { queryKey: getListFavoritesQueryKey() } });
  const savedIds = useMemo(() => new Set((savedQuery.data ?? []).map((property) => property.id)), [savedQuery.data]);
  return <><PublicHeader /><main className="mx-auto min-h-[calc(100dvh-72px)] max-w-7xl px-5 py-10 lg:px-8"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="font-mono-custom text-xs uppercase tracking-[.18em] text-accent">Property index</p><h1 className="mt-2 font-display text-4xl font-bold tracking-tight md:text-5xl">Homes for your next chapter.</h1><p className="mt-3 text-sm text-muted-foreground">Start with a place, then look at the details.</p></div><Link href="/search" data-testid="link-advanced-search" className="flex items-center gap-2 text-sm font-bold text-primary underline-link">Advanced search <SlidersHorizontal size={15} /></Link></div><div className="mt-8 rounded-2xl border border-border bg-card p-2"><SearchBar compact initial={location} /></div><div className="mt-4 grid gap-2 rounded-2xl border border-border bg-card p-3 sm:grid-cols-2 lg:grid-cols-5"><input value={minRent} onChange={(event) => setMinRent(event.target.value)} type="number" min="0" placeholder="Min rent (UGX)" data-testid="input-filter-min-rent" className="rounded-xl bg-muted px-3 py-2.5 text-xs font-semibold outline-none focus:ring-2 focus:ring-primary" /><input value={maxRent} onChange={(event) => setMaxRent(event.target.value)} type="number" min="0" placeholder="Max rent (UGX)" data-testid="input-filter-max-rent" className="rounded-xl bg-muted px-3 py-2.5 text-xs font-semibold outline-none focus:ring-2 focus:ring-primary" /><select value={bedrooms} onChange={(event) => setBedrooms(event.target.value)} data-testid="select-filter-bedrooms" className="rounded-xl bg-muted px-3 py-2.5 text-xs font-semibold outline-none"><option value="">Any bedrooms</option><option value="1">1+ bedroom</option><option value="2">2+ bedrooms</option><option value="3">3+ bedrooms</option></select><select value={advanceMonths} onChange={(event) => setAdvanceMonths(event.target.value)} data-testid="select-filter-advance" className="rounded-xl bg-muted px-3 py-2.5 text-xs font-semibold outline-none"><option value="">Any advance</option><option value="1">Up to 1 month</option><option value="3">Up to 3 months</option><option value="6">Up to 6 months</option></select><input value={amenity} onChange={(event) => setAmenity(event.target.value)} placeholder="Amenity e.g. parking" data-testid="input-filter-amenity" className="rounded-xl bg-muted px-3 py-2.5 text-xs font-semibold outline-none focus:ring-2 focus:ring-primary" /></div><div className="mt-8 flex flex-wrap items-center justify-between gap-3"><p className="text-sm font-semibold text-muted-foreground"><span className="font-display text-lg font-bold text-foreground">{data?.length ?? 0}</span> homes to explore</p><div className="flex flex-wrap items-center gap-2"><select value={type} onChange={(event) => setType(event.target.value)} data-testid="select-filter-type" className="rounded-xl border border-border bg-card px-3 py-2 text-xs font-bold outline-none"><option value="">All types</option><option value="Apartment">Apartments</option><option value="House">Houses</option><option value="Studio">Studios</option><option value="Single room">Single rooms</option><option value="Bungalow">Bungalows</option></select><select value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} data-testid="select-sort-properties" className="rounded-xl border border-border bg-card px-3 py-2 text-xs font-bold outline-none"><option value="recommended">Recommended</option><option value="lowest">Lowest rent</option><option value="highest">Highest rent</option><option value="newest">Newest</option><option value="viewed">Most viewed</option></select></div></div><div className="mt-6"><QueryState loading={isLoading} error={isError} retry={() => refetch()}><PropertyGrid properties={properties} savedIds={savedIds} onFavoriteChanged={() => savedQuery.refetch()} /></QueryState></div></main><Footer /></>;
}

function SearchPage() {
  const [saved, setSaved] = useState(false);
  const [form, setForm] = useState({ location: 'Kampala', type: 'Any type', maxRent: '2000000', bedrooms: '1 bedroom' });
  const create = useCreateSavedSearch();
  const update = (key: keyof typeof form, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const typeSummary = form.type === 'Any type' ? 'Any home' : form.type;
    create.mutate({ data: { name: `${form.location} ${typeSummary} search`, location: form.location, summary: `${typeSummary} · up to ${form.maxRent} · ${form.bedrooms}` } }, { onSuccess: () => setSaved(true) });
  };
  return <><PublicHeader /><main className="mx-auto min-h-[calc(100dvh-72px)] max-w-5xl px-5 py-12 lg:px-8"><div className="max-w-2xl"><p className="font-mono-custom text-xs uppercase tracking-[.18em] text-accent">Search deliberately</p><h1 className="mt-3 font-display text-5xl font-bold leading-[.98] tracking-[-.05em] md:text-7xl">Your next home,<br /><span className="text-primary">on your terms.</span></h1><p className="mt-5 text-base leading-7 text-muted-foreground">Tell us what matters. We will keep the noise out of the way.</p></div><form onSubmit={submit} className="mt-12 grid gap-5 rounded-[2rem] border border-border bg-card p-5 shadow-sm md:grid-cols-2 md:p-8"><label className="text-sm font-bold">Where are you looking?<input value={form.location} onChange={(event) => update('location', event.target.value)} required data-testid="input-search-location" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 font-medium outline-none ring-primary focus:ring-2" /></label><label className="text-sm font-bold">Home type<select value={form.type} onChange={(event) => update('type', event.target.value)} data-testid="select-search-type" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 font-medium outline-none"><option>Any type</option><option>Apartment</option><option>House</option><option>Studio</option><option>Single room</option></select></label><label className="text-sm font-bold">Monthly rent up to<select value={form.maxRent} onChange={(event) => update('maxRent', event.target.value)} data-testid="select-search-rent" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 font-medium outline-none"><option value="1000000">UGX 1,000,000</option><option value="2000000">UGX 2,000,000</option><option value="3000000">UGX 3,000,000</option><option value="5000000">UGX 5,000,000</option></select></label><label className="text-sm font-bold">At least bedrooms<select value={form.bedrooms} onChange={(event) => update('bedrooms', event.target.value)} data-testid="select-search-bedrooms" className="mt-2 w-full rounded-xl border border-input bg-background px-4 py-3 font-medium outline-none"><option value="0">Any size</option><option value="1">1 bedroom</option><option value="2">2 bedrooms</option><option value="3">3 bedrooms</option></select></label><div className="flex items-center justify-between gap-4 md:col-span-2 md:border-t md:border-border md:pt-5"><p className="text-xs text-muted-foreground">{saved ? 'Search saved. We will keep an eye on new matches.' : 'Save this search and get a quieter way to keep up.'}</p><Button type="submit" disabled={create.isPending || saved}>{saved ? <><Check size={16} /> Saved</> : <><Bell size={16} /> Save search</>}</Button></div></form><div className="mt-12 grid gap-4 sm:grid-cols-3"><div className="rounded-2xl bg-primary p-5 text-primary-foreground"><Search size={19} className="text-secondary" /><h3 className="mt-8 font-display font-bold">Search by real places</h3><p className="mt-2 text-xs leading-5 text-primary-foreground/70">Neighbourhoods, districts and landmarks you actually use.</p></div><div className="rounded-2xl border border-border bg-card p-5"><ShieldCheck size={19} className="text-primary" /><h3 className="mt-8 font-display font-bold">Details before drama</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">Rent and advance are visible before you make the call.</p></div><div className="rounded-2xl border border-border bg-secondary/30 p-5"><Heart size={19} /><h3 className="mt-8 font-display font-bold">Keep a shortlist</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">Save the maybes. Return when your head is clear.</p></div></div></main><Footer /></>;
}

function PropertyDetail() {
  const { id = '' } = useParams<{ id: string }>();
  const { data, isLoading, isError, refetch } = useGetProperty(id, { query: { enabled: !!id, queryKey: getGetPropertyQueryKey(id) } });
  const property = data || sampleProperties.find((item) => item.id === id) || sampleProperties[0];
  const [saved, setSaved] = useState(false);
  const [contacted, setContacted] = useState(false);
  const [reportOpen, setReportOpen] = useState(false);
  const favoriteAdd = useAddFavorite();
  const favoriteRemove = useRemoveFavorite();
  const report = useReportProperty();
  const submitReport = () => { report.mutate({ data: { propertyId: id, reason: 'Listing details need checking' } }, { onSuccess: () => setReportOpen(false) }); };
  const toggleSaved = () => {
    const mutation = saved ? favoriteRemove : favoriteAdd;
    mutation.mutate({ propertyId: property.id }, {
      onSuccess: () => {
        setSaved((value) => !value);
        queryClient.invalidateQueries({ queryKey: getListFavoritesQueryKey() });
      },
    });
  };
  const phone = property.owner.phone.replace(/[^\d+]/g, '').replace(/^\+/, '');
  const whatsappHref = `https://wa.me/${phone}?text=${encodeURIComponent(`Hi ${property.owner.name}, I am interested in ${property.title} on Homza.`)}`;
  if (isLoading && !property) return <><PublicHeader /><main className="mx-auto max-w-7xl px-5 py-12"><div className="skeleton h-96 rounded-3xl" /></main></>;
  return <><PublicHeader /><main className="mx-auto max-w-7xl px-5 py-8 pb-28 lg:px-8 lg:pb-8"><Link href="/properties" data-testid="link-back-properties" className="mb-6 inline-flex items-center gap-2 text-sm font-bold text-muted-foreground hover:text-primary"><ChevronLeft size={16} /> All homes</Link><QueryState loading={false} error={isError && !data} retry={() => refetch()}><div className="grid gap-6 lg:grid-cols-[1.3fr_.7fr]"><div><div className="grid aspect-[1.4] gap-2 overflow-hidden rounded-3xl sm:grid-cols-[1.4fr_.6fr]"><img src={property.image || photos[0]} alt={property.title} className="h-full w-full object-cover" /><div className="hidden gap-2 sm:grid">{(property.images || photos.slice(1, 3)).slice(0, 2).map((image, index) => <img key={image} src={image} alt={`${property.title} view ${index + 2}`} className="h-full min-h-0 w-full object-cover" />)}</div></div><div className="mt-8"><div className="flex flex-wrap items-center gap-2"><StatusPill verified={property.verified} status={property.status} /><span className="font-mono-custom text-xs text-muted-foreground">{property.type}</span></div><h1 className="mt-3 font-display text-4xl font-bold tracking-tight md:text-5xl">{property.title}</h1><p className="mt-3 flex items-center gap-1.5 text-sm text-muted-foreground"><MapPin size={15} className="text-accent" /> {property.location} · {property.district}</p><div className="mt-8 grid grid-cols-3 border-y border-border py-4 text-center text-sm font-semibold"><div><BedDouble className="mx-auto mb-2 text-primary" size={18} />{property.bedrooms} bedrooms</div><div><House className="mx-auto mb-2 text-primary" size={18} />{property.bathrooms} bathrooms</div><div><Landmark className="mx-auto mb-2 text-primary" size={18} />{property.size || '—'} m²</div></div><h2 className="mt-8 font-display text-xl font-bold">About this home</h2><p className="mt-3 max-w-2xl text-sm leading-7 text-muted-foreground">{property.description || 'A well-kept home in a neighbourhood with the essentials close by.'}</p><h2 className="mt-8 font-display text-xl font-bold">What is included</h2><div className="mt-4 flex flex-wrap gap-2">{property.amenities.map((amenity) => <span key={amenity} className="rounded-full bg-muted px-3 py-2 text-xs font-semibold">{amenity}</span>)}</div><button onClick={() => setReportOpen((value) => !value)} data-testid="button-report-property" className="mt-10 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground underline underline-offset-4 hover:text-destructive"><CircleAlert size={14} /> Something not right?</button>{reportOpen && <div className="mt-4 flex max-w-lg items-center justify-between gap-4 rounded-xl border border-destructive/20 bg-destructive/5 p-4 text-xs"><span>Tell us and our trust team will check this listing.</span><Button onClick={submitReport} disabled={report.isPending} variant="danger" className="px-3 py-2 text-xs">{report.isPending ? 'Sending…' : 'Report listing'}</Button></div>}</div></div><aside><div className="sticky top-24 rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-xs font-bold uppercase tracking-[.13em] text-muted-foreground">Monthly rent</p><p className="mt-1 font-display text-3xl font-bold text-primary">{money(property.rent)}</p><p className="mt-1 text-xs text-muted-foreground">{property.advanceMonths} months advance · negotiable with owner</p><div className="my-6 border-t border-border" /><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-full bg-secondary font-display font-bold">{property.owner.initials || initials(property.owner.name)}</span><div><p className="flex items-center gap-1 text-sm font-bold">{property.owner.name} {property.owner.verified && <BadgeCheck className="text-primary" size={14} />}</p><p className="text-xs text-muted-foreground">Listing owner</p></div></div><Button onClick={() => setContacted(true)} data-testid="button-contact-owner" className="mt-5 w-full">{contacted ? <><CircleCheck size={17} /> Message sent</> : <><MessageCircle size={17} /> Contact owner</>}</Button><Button onClick={toggleSaved} disabled={favoriteAdd.isPending || favoriteRemove.isPending} data-testid="button-detail-save" variant="outline" className="mt-2 w-full">{saved ? <><Check size={16} /> Saved to shortlist</> : <><Heart size={16} /> Save this home</>}</Button><div className="mt-4 grid grid-cols-2 gap-2"><a href={whatsappHref} target="_blank" rel="noreferrer" data-testid="link-whatsapp-owner" className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#168c4e] px-3 py-2.5 text-xs font-bold text-white"><MessageCircle size={15} /> WhatsApp</a><a href={`tel:${property.owner.phone}`} data-testid="link-call-owner" className="inline-flex items-center justify-center gap-2 rounded-xl border border-border px-3 py-2.5 text-xs font-bold"><LifeBuoy size={15} /> Call</a></div><p className="mt-4 text-center text-[11px] leading-5 text-muted-foreground">Keep conversations on Homza. Never pay before seeing the home.</p></div><div className="mt-4 flex gap-3 rounded-2xl border border-border bg-secondary/20 p-4 text-xs leading-5"><ShieldCheck className="shrink-0 text-primary" size={17} /><span><strong>Homza note:</strong> Verified means we have checked the owner details and listing information recently.</span></div></aside></div></QueryState></main><div className="fixed inset-x-0 bottom-0 z-30 flex gap-2 border-t border-border bg-card/95 p-3 backdrop-blur lg:hidden"><a href={whatsappHref} target="_blank" rel="noreferrer" data-testid="mobile-whatsapp-owner" className="inline-flex flex-1 items-center justify-center gap-2 rounded-xl bg-[#168c4e] px-3 py-3 text-sm font-bold text-white"><MessageCircle size={17} /> WhatsApp owner</a><a href={`tel:${property.owner.phone}`} data-testid="mobile-call-owner" className="inline-flex flex-1 items-center justify-center gap-2 rounded-xl border border-border bg-background px-3 py-3 text-sm font-bold"><LifeBuoy size={17} /> Call owner</a></div></>;
}

const tenantNav = [{ href: '/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/dashboard/saved', label: 'Saved homes', icon: Heart }, { href: '/dashboard/searches', label: 'Saved searches', icon: Bell }, { href: '/dashboard/messages', label: 'Messages', icon: MessageCircle }, { href: '/dashboard/profile', label: 'Profile', icon: User }];
const ownerNav = [{ href: '/owner', label: 'Overview', icon: LayoutDashboard }, { href: '/owner/properties', label: 'My properties', icon: Building2 }, { href: '/owner/leads', label: 'Leads', icon: Users }, { href: '/owner/messages', label: 'Messages', icon: MessageCircle }, { href: '/owner/analytics', label: 'Analytics', icon: BarChart3 }, { href: '/owner/payments', label: 'Payments', icon: CreditCard }, { href: '/owner/subscription', label: 'Subscription', icon: Zap }, { href: '/owner/profile', label: 'Profile', icon: User }];
const adminNav = [{ href: '/admin', label: 'Overview', icon: LayoutDashboard }, { href: '/admin/users', label: 'Users', icon: Users }, { href: '/admin/owners', label: 'Owners', icon: ShieldCheck }, { href: '/admin/verification', label: 'Verification', icon: BadgeCheck }, { href: '/admin/properties', label: 'Moderation', icon: Building2 }, { href: '/admin/reports', label: 'Reports', icon: CircleAlert }, { href: '/admin/payments', label: 'Payments', icon: CreditCard }, { href: '/admin/subscriptions', label: 'Subscriptions', icon: Zap }, { href: '/admin/archived', label: 'Archived', icon: ClipboardList }, { href: '/admin/settings', label: 'Settings', icon: Settings }];

function AppShell({ role, children }: { role: 'tenant' | 'owner' | 'admin'; children: React.ReactNode }) {
  const [mobile, setMobile] = useState(false);
  const nav = role === 'tenant' ? tenantNav : role === 'owner' ? ownerNav : adminNav;
  const title = role === 'tenant' ? 'Tenant workspace' : role === 'owner' ? 'Owner workspace' : 'Trust console';
  return <div className="min-h-[100dvh] bg-background"><aside className={`fixed inset-y-0 left-0 z-50 flex w-[245px] flex-col border-r border-border bg-foreground text-background transition-transform md:translate-x-0 ${mobile ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex h-[72px] items-center border-b border-background/10 px-5"><Logo inverse /><button onClick={() => setMobile(false)} data-testid="button-close-sidebar" className="ml-auto rounded-lg p-1 text-background/60 md:hidden"><X size={18} /></button></div><div className="flex flex-1 flex-col px-3 py-5"><p className="px-3 text-[10px] font-bold uppercase tracking-[.18em] text-background/40">{title}</p><nav className="mt-4 flex flex-col gap-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-sidebar-${label.toLowerCase().replace(' ', '-')}`} className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-background/65 transition hover:bg-background/10 hover:text-background"><Icon size={17} />{label}</Link>)}</nav><div className="mt-auto rounded-2xl bg-background/10 p-4"><p className="text-xs font-bold text-secondary">Need a hand?</p><p className="mt-1 text-[11px] leading-5 text-background/55">Our team is one message away.</p><Link href="/contact" data-testid="link-sidebar-help" className="mt-3 inline-flex text-xs font-bold text-background underline underline-offset-4">Get support <ArrowUpRight size={13} /></Link></div></div><div className="border-t border-background/10 p-4"><div className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-secondary text-xs font-bold text-foreground">AK</span><div className="min-w-0"><p className="truncate text-xs font-bold">Akol D.</p><p className="text-[10px] text-background/50">Kampala, Uganda</p></div><MoreHorizontal className="ml-auto text-background/45" size={17} /></div></div></aside><div className="md:pl-[245px]"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-border bg-background/95 px-5 backdrop-blur lg:px-8"><button onClick={() => setMobile(true)} data-testid="button-open-sidebar" className="rounded-lg p-2 md:hidden"><Menu size={20} /></button><div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex"><span className="h-2 w-2 rounded-full bg-primary" /> All systems ready</div><div className="ml-auto flex items-center gap-3"><button data-testid="button-notifications" className="relative rounded-xl border border-border bg-card p-2.5 text-muted-foreground hover:text-primary"><Bell size={17} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-accent" /></button><Link href="/" data-testid="link-back-to-homes" className="hidden items-center gap-2 rounded-xl border border-border bg-card px-3 py-2 text-xs font-bold sm:flex">Browse homes <ArrowUpRight size={14} /></Link></div></header><main className="min-h-[calc(100dvh-72px)] p-5 lg:p-8">{children}</main></div></div>;
}

function StatCard({ label, value, icon: Icon, accent = false, trend }: { label: string; value: string | number; icon: typeof HomeIcon; accent?: boolean; trend?: string }) {
  return <div className={`rounded-2xl border p-5 ${accent ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card'}`}><div className="flex items-start justify-between"><span className={`grid h-9 w-9 place-items-center rounded-xl ${accent ? 'bg-primary-foreground/15 text-secondary' : 'bg-muted text-primary'}`}><Icon size={18} /></span>{trend && <span className={`text-[11px] font-bold ${accent ? 'text-secondary' : 'text-primary'}`}>{trend}</span>}</div><p className={`mt-7 text-xs font-bold ${accent ? 'text-primary-foreground/65' : 'text-muted-foreground'}`}>{label}</p><p className="mt-1 font-display text-3xl font-bold">{value}</p></div>;
}

function Dashboard() {
  const { data, isLoading, isError, refetch } = useGetTenantDashboard({ query: { queryKey: getGetTenantDashboardQueryKey() } });
  const fallback = { savedProperties: 3, savedSearches: 2, recentViews: 8, messages: 2, recommended: sampleProperties.slice(0, 3), nearby: sampleProperties.slice(1, 3), recentlyViewed: sampleProperties.slice(0, 2) };
  const dash = data || fallback;
  return <AppShell role="tenant"><div className="mx-auto max-w-6xl"><div className="animate-rise flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="font-mono-custom text-xs uppercase tracking-[.18em] text-accent">Tuesday, 25 June 2024</p><h1 className="mt-2 font-display text-3xl font-bold tracking-tight md:text-4xl">Good morning, Akol.</h1><p className="mt-2 text-sm text-muted-foreground">Let’s find the place that makes the rest easier.</p></div><Link href="/properties" data-testid="link-dashboard-search" className="inline-flex items-center gap-2 self-start rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground sm:self-auto">Find a home <Search size={16} /></Link></div><QueryState loading={isLoading} error={isError && !data} retry={() => refetch()}><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Saved homes" value={dash.savedProperties} icon={Heart} accent trend="Your shortlist" /><StatCard label="Saved searches" value={dash.savedSearches} icon={Bell} /><StatCard label="Homes viewed" value={dash.recentViews} icon={Compass} trend="This month" /><StatCard label="Messages" value={dash.messages} icon={MessageCircle} /></div><div className="mt-8 grid gap-8 xl:grid-cols-[1.3fr_.7fr]"><section><div className="flex items-center justify-between"><div><p className="font-mono-custom text-xs uppercase tracking-[.16em] text-accent">Picked for you</p><h2 className="mt-1 font-display text-xl font-bold">Homes that fit your search</h2></div><Link href="/properties" data-testid="link-dashboard-recommendations" className="text-xs font-bold text-primary underline-link">See more</Link></div><div className="mt-4 grid gap-4 sm:grid-cols-2">{dash.recommended.slice(0, 2).map((property) => <PropertyCard key={property.id} property={property} />)}</div></section><section className="rounded-2xl border border-border bg-secondary/25 p-5"><div className="flex items-start justify-between"><div><p className="font-mono-custom text-xs uppercase tracking-[.16em] text-accent">Your rhythm</p><h2 className="mt-1 font-display text-xl font-bold">Keep looking lightly.</h2></div><Sparkles className="text-accent" size={19} /></div><p className="mt-5 text-sm leading-6 text-muted-foreground">You have 3 homes saved around Kampala. A few more details could make your shortlist feel certain.</p><Link href="/dashboard/saved" data-testid="link-dashboard-saved" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-primary underline-link">Open shortlist <ArrowRight size={15} /></Link><div className="mt-8 border-t border-border/70 pt-4"><p className="text-xs font-bold">New on your saved search</p><p className="mt-1 text-xs text-muted-foreground">2 homes in Ntinda match your budget.</p></div></section></div></QueryState></div></AppShell>;
}

function SavedPage() {
  const { data, isLoading, isError, refetch } = useListFavorites({ query: { queryKey: getListFavoritesQueryKey() } });
  const properties = data ?? [];
  const removeFavorite = () => queryClient.invalidateQueries({ queryKey: getListFavoritesQueryKey() });
  return <AppShell role="tenant"><PageHeading eyebrow="Your shortlist" title="Saved homes" copy="The homes you did not want to lose." action={<Link href="/properties" data-testid="link-saved-find-more" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground">Find more <Search size={16} /></Link>} /><div className="mt-8"><QueryState loading={isLoading} error={isError} retry={() => refetch()}><PropertyGrid properties={properties} empty="You haven't saved any properties yet. Start with a few homes that feel promising." savedIds={new Set(properties.map((property) => property.id))} onFavoriteChanged={removeFavorite} /></QueryState></div></AppShell>;
}

function SearchesPage() {
  const { data, isLoading, refetch } = useListSavedSearches({ query: { queryKey: getListSavedSearchesQueryKey() } });
  const [created, setCreated] = useState(false);
  const create = useCreateSavedSearch();
  const searches = data ?? [];
  const make = () => { create.mutate({ data: { name: 'New Kampala search', location: 'Kampala', summary: 'Any home · 1+ bedroom' } }, { onSuccess: () => { setCreated(true); queryClient.invalidateQueries({ queryKey: getListSavedSearchesQueryKey() }); } }); };
  return <AppShell role="tenant"><PageHeading eyebrow="Stay in the loop" title="Saved searches" copy="A small watchlist for the places that matter." action={<Button onClick={make} disabled={create.isPending || created} data-testid="button-create-search">{created ? <><Check size={16} /> Search saved</> : <><Plus size={16} /> New search</>}</Button>} /><div className="mt-8">{isLoading ? <div className="grid gap-4 md:grid-cols-2">{[1, 2].map((item) => <div key={item} className="skeleton h-40 rounded-2xl" />)}</div> : searches.length ? <div className="grid gap-4 md:grid-cols-2">{searches.map((search) => <div key={search.id} data-testid={`card-search-${search.id}`} className="rounded-2xl border border-border bg-card p-5"><div className="flex items-start justify-between"><span className="grid h-9 w-9 place-items-center rounded-xl bg-secondary"><Bell size={17} /></span><button data-testid={`button-search-menu-${search.id}`} className="text-muted-foreground"><MoreHorizontal size={18} /></button></div><h3 className="mt-5 font-display text-xl font-bold">{search.name}</h3><p className="mt-1 text-sm text-muted-foreground">{search.location} · {search.summary}</p><div className="mt-5 flex items-center justify-between border-t border-border pt-4 text-xs"><span className="font-bold text-primary">{search.matches} matching homes</span><span className="text-muted-foreground">Updated {search.updatedAt}</span></div></div>)}</div> : <div className="rounded-2xl border border-dashed border-border bg-card py-14 text-center"><Bell className="mx-auto text-primary" size={27} /><h2 className="mt-4 font-display text-xl font-bold">No saved searches yet</h2><p className="mt-2 text-sm text-muted-foreground">Save a search when you want Homza to keep watch.</p><Link href="/search" className="mt-5 inline-flex font-bold text-primary underline-link">Build a search <ArrowRight size={15} className="ml-1" /></Link></div>}</div></AppShell>;
}

function MessagesPage({ owner = false }: { owner?: boolean }) {
  const messages = owner ? [{ name: 'Sarah Nakato', subject: 'Viewing request · Sunlit bungalow', time: '10:42' }, { name: 'Daniel O.', subject: 'Question about parking', time: 'Yesterday' }] : [{ name: 'Amina N.', subject: 'Re: Quiet two-bedroom near the lake', time: '09:18' }, { name: 'Homza team', subject: 'Your saved search found 2 new homes', time: 'Mon' }];
  const [selected, setSelected] = useState(0);
  const [draft, setDraft] = useState('');
  const [sent, setSent] = useState<string[]>([]);
  const active = messages[selected] || messages[0];
  const send = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const text = draft.trim();
    if (!text) return;
    setSent((items) => [...items, text]);
    setDraft('');
  };
  return <AppShell role={owner ? 'owner' : 'tenant'}><PageHeading eyebrow="Keep it human" title="Messages" copy={owner ? 'Conversations that could become keys.' : 'Your conversations, without the hunt.'} /><div className="mt-8 grid overflow-hidden rounded-2xl border border-border bg-card lg:grid-cols-[.75fr_1.25fr]"><div className="border-b border-border lg:border-b-0 lg:border-r">{messages.map((message, index) => <button key={message.name} data-testid={`button-message-${index}`} className={`flex w-full items-start gap-3 border-b border-border p-5 text-left transition hover:bg-muted ${index === 0 ? 'bg-muted/55' : ''}`}><span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-secondary text-xs font-bold">{initials(message.name)}</span><span className="min-w-0 flex-1"><span className="flex justify-between gap-3 text-sm font-bold"><span className="truncate">{message.name}</span><span className="text-[11px] text-muted-foreground">{message.time}</span></span><span className="mt-1 block truncate text-xs text-muted-foreground">{message.subject}</span></span></button>)}</div><div className="hidden min-h-[390px] flex-col lg:flex"><div className="flex items-center gap-3 border-b border-border p-5"><span className="grid h-10 w-10 place-items-center rounded-full bg-secondary text-xs font-bold">{initials(messages[0].name)}</span><div><p className="text-sm font-bold">{messages[0].name}</p><p className="text-xs text-muted-foreground">Usually replies within a day</p></div></div><div className="flex flex-1 flex-col justify-end gap-3 p-5"><div className="max-w-sm rounded-2xl rounded-bl-sm bg-muted p-3 text-sm leading-6">Hi Akol, thanks for reaching out. Would Saturday morning work for a viewing?</div><div className="max-w-sm self-end rounded-2xl rounded-br-sm bg-primary p-3 text-sm leading-6 text-primary-foreground">Saturday works well. I’ll be there at 10am.</div></div><form onSubmit={(event) => event.preventDefault()} className="flex gap-2 border-t border-border p-4"><input data-testid="input-message-reply" className="min-w-0 flex-1 rounded-xl bg-muted px-4 py-3 text-sm outline-none" placeholder="Write a reply..." /><Button type="submit" className="px-3" data-testid="button-send-message"><Send size={16} /></Button></form></div></div></AppShell>;
}

